using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps;using MapSharedProps.EditorTools;
public static class RootBarkTransportChecks {
 [Serializable]class Row{public string name;public bool passed;}[Serializable]class Report{public string status;public Row[] checks;}
 static List<Row> rows=new List<Row>();static void Check(string name,bool ok){rows.Add(new Row{name=name,passed=ok});if(!ok)throw new Exception(name);}static string Arg(string key){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,key)+1];}
 public static void Run(){string output=Arg("-nature-output");int code=0;try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var built=MapSharedPropsBuilder.Build(Path.Combine(output,"slope-export"));Check("26 exported placements import",built.placed==26&&built.skipped==0);var lib=MapSharedPropsBuilder.ReadLibrary(Path.Combine(output,"slope-export/shared_props.json"));var manager=built.root.GetComponent<SharedPlantContact>();var actor=new GameObject("contact source").AddComponent<SharedPlantContactSource>();actor.height=1.8f;actor.radius=.3f;manager.source=actor;manager.useClock=false;int roots=0;
 foreach(var e in manager.entries){var mesh=e.renderer.GetComponent<MeshFilter>().sharedMesh;var a=Array.Find(lib.assets,x=>built.prefabs[x.id].GetComponent<MeshFilter>().sharedMesh==mesh);if(a==null||a.rootGrounding==null)continue;roots++;var block=new MaterialPropertyBlock();e.renderer.GetPropertyBlock(block);Check(a.id+" reflected exported slope",Vector2.Distance(new Vector2(block.GetVector("_TDRootSlope").x,block.GetVector("_TDRootSlope").y),new Vector2(.1f,-.04f))<.00001f);actor.transform.position=e.renderer.transform.position+new Vector3(.08f,0,.1f);for(int i=0;i<180;i++)manager.Step(1/60f);e.renderer.GetPropertyBlock(block);Check(a.id+" contact preserves root plane",Vector2.Distance(new Vector2(block.GetVector("_TDRootSlope").x,block.GetVector("_TDRootSlope").y),new Vector2(.1f,-.04f))<.00001f);actor.transform.position=new Vector3(1000,0,1000);for(int i=0;i<360;i++)manager.Step(1/60f);Check(a.id+" returns to rest on slope",e.bend==Vector2.zero&&e.velocity==Vector2.zero);
 e.renderer.transform.localScale=new Vector3(1.6f,.2f,.7f);SharedRootGrounding.SetSlope(e.renderer,new Vector2(.1f,-.04f));manager.Refresh();var b=e.renderer.localBounds;bool inside=true;for(int i=0;i<mesh.vertexCount;i++){var p=mesh.vertices[i];var wp=e.renderer.localToWorldMatrix.MultiplyPoint3x4(p);var origin=e.renderer.transform.position;wp.y+=(.1f*(wp.x-origin.x)-.04f*(wp.z-origin.z))*a.rootWeights[i];inside&=b.Contains(e.renderer.worldToLocalMatrix.MultiplyPoint3x4(wp));}Check(a.id+" root bounds contain non-uniform scale",inside);}
 Check("24 optional root planes applied",roots==24);
 }catch(Exception e){code=1;Debug.LogException(e);}File.WriteAllText(Path.Combine(output,"roots-transport-unity.json"),JsonUtility.ToJson(new Report{status=code==0?"Passed":"Failed",checks=rows.ToArray()},true));EditorApplication.Exit(code);}
}
